def flatten(lst):
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

Example: flatten([1, [2, [3, 4]], 5]) returns [1, 2, 3, 4, 5]. This handles arbitrary nesting depth via recursion.

class Stack:
    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._data.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError('peek at empty stack')
        return self._data[-1]

    def is_empty(self):
        return len(self._data) == 0

    def __len__(self):
        return len(self._data)

from collections import Counter

def word_frequency(text: str) -> dict[str, int]:
    words = text.lower().split()
    return dict(Counter(words))

This lowercases the text, splits on whitespace, and counts occurrences using Counter. For production use, also strip punctuation: import re; words = re.findall(r'\b\w+\b', text.lower())
